-- Foto de temporada (Halloween) lista pero SIN publicar. Se activa desde Admin → Mensaje de los dueños
-- (palomita "Visible") cuando la clienta apruebe el saludo. Mientras esté oculta, la foto no se sirve públicamente.
DO $$
DECLARE mid BIGINT;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM owner_posts WHERE title = '¡Feliz Halloween!') THEN
    INSERT INTO media (mime, size_bytes, data)
    VALUES ('image/jpeg', 156793, decode('', 'base64'))
    RETURNING id INTO mid;
    INSERT INTO owner_posts (title, body, author, photo_id, is_active)
    VALUES ('¡Feliz Halloween!', '¡Feliz Halloween de parte de la familia Ayora!', 'Familia Ayora', mid, FALSE);
  END IF;
END $$;

INSERT INTO audit_log (action, entity, entity_id, summary)
VALUES ('system.migration', 'system', '007', 'Migración 007: foto de Halloween cargada sin publicar');
